 // [ ESAME 2025-06-05
 	p->swapped_out = false;
+	p->scheduled = false;
 //   ESAME 2025-06-05 ]

 	// selezione di un identificatore
@@ -1853,6 +1854,128 @@ void process_dump(des_proc* p, log_sev sev)


 // ( SOLUZIONE 2025-06-05
+
+extern "C" void c_swap_out(natl pid, char *buf)
+{
+    // Check pid validity (in range and allocated)
+    if (pid > MAX_PROC_ID || !proc_table[pid]) {
+        flog(LOG_WARN, "swap_out: pid non valido: %u", pid);
+        c_abort_p();
+        return;
+    }
+
+    des_proc* p = proc_table[pid];
+
+    // Check not a system process
+    if (p->livello == LIV_SISTEMA) {
+        flog(LOG_WARN, "swap_out: processo di sistema: %u", pid);
+        c_abort_p();
+        return;
+    }
+
+    // Check not self
+    if (p == esecuzione) {
+        flog(LOG_WARN, "swap_out: stesso processo invocante: %u", pid);
+        c_abort_p();
+        return;
+    }
+
+    // Trojan horse check - buffer must be writable and in user/shared area
+    if (!c_access((vaddr)buf, DIM_USR_STACK, true, true)) {
+        flog(LOG_WARN, "swap_out: buffer non valido");
+        c_abort_p();
+        return;
+    }
+
+    // Check not already swapped out
+    if (p->swapped_out) {
+        esecuzione->contesto[I_RAX] = false;
+        return;
+    }
+
+    // Copy user stack to buffer
+    vaddr stack_start = fin_utn_p - DIM_USR_STACK;
+    natq n_pages = DIM_USR_STACK / DIM_PAGINA;
+    for (natq page = 0; page < n_pages; page++) {
+        vaddr v = stack_start + page * DIM_PAGINA;
+        paddr pa = trasforma(p->cr3, v);
+        if (pa) {
+            memcpy(buf + page * DIM_PAGINA, voidptr_cast(pa), DIM_PAGINA);
+        } else {
+            memset(buf + page * DIM_PAGINA, 0, DIM_PAGINA);
+        }
+    }
+
+    // Destroy user stack (unmap and deallocate frames)
+    distruggi_pila(p->cr3, fin_utn_p, DIM_USR_STACK);
+
+    // Set swapped_out flag
+    p->swapped_out = true;
+
+    // Return true
+    esecuzione->contesto[I_RAX] = true;
+}
+
+extern "C" void c_swap_in(natl pid, const char *buf)
+{
+    // Check pid validity (in range and allocated)
+    if (pid > MAX_PROC_ID || !proc_table[pid]) {
+        flog(LOG_WARN, "swap_in: pid non valido: %u", pid);
+        c_abort_p();
+        return;
+    }
+
+    des_proc* p = proc_table[pid];
+
+    // Check not a system process
+    if (p->livello == LIV_SISTEMA) {
+        flog(LOG_WARN, "swap_in: processo di sistema: %u", pid);
+        c_abort_p();
+        return;
+    }
+
+    // Trojan horse check - buffer must be readable and in user/shared area
+    if (!c_access((vaddr)buf, DIM_USR_STACK, false, true)) {
+        flog(LOG_WARN, "swap_in: buffer non valido");
+        c_abort_p();
+        return;
+    }
+
+    // Check is swapped out
+    if (!p->swapped_out) {
+        esecuzione->contesto[I_RAX] = false;
+        return;
+    }
+
+    // Create user stack
+    if (!crea_pila(p->cr3, fin_utn_p, DIM_USR_STACK, LIV_UTENTE)) {
+        esecuzione->contesto[I_RAX] = false;
+        return;
+    }
+
+    // Copy buffer to user stack
+    vaddr stack_start = fin_utn_p - DIM_USR_STACK;
+    natq n_pages = DIM_USR_STACK / DIM_PAGINA;
+    for (natq page = 0; page < n_pages; page++) {
+        vaddr v = stack_start + page * DIM_PAGINA;
+        paddr pa = trasforma(p->cr3, v);
+        memcpy(voidptr_cast(pa), buf + page * DIM_PAGINA, DIM_PAGINA);
+    }
+
+    // Clear swapped_out flag
+    p->swapped_out = false;
+
+    // Set return value before potentially changing esecuzione
+    esecuzione->contesto[I_RAX] = true;
+
+    // If process was scheduled while swapped out, re-insert and preempt
+    if (p->scheduled) {
+        p->scheduled = false;
+        inspronti();            // preemption: insert current process in ready queue
+        inserimento_lista(pronti, p);
+        schedulatore();
+    }
+}
 //   SOLUZIONE 2025-06-05 )


